css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: calc(var(--loader-size) * .84); position: relative; display: flex; flex-direction: column; justify-content: space-between; padding: 5% 4%; border-radius: 4px; overflow: hidden; perspective: 420px; background: linear-gradient(color-mix(in srgb, #fff 58%, var(--accent-2)), color-mix(in srgb, #fff 18%, var(--accent-2))); }
.loader span { height: 12%; border-radius: 2px; background: linear-gradient(var(--accent), color-mix(in srgb, #000 24%, var(--accent))); animation: tilt-slat calc(var(--loader-speed) * 2.8) ease-in-out infinite; }
.loader span:nth-child(2) { animation-delay: calc(var(--loader-speed) * .07); }
.loader span:nth-child(3) { animation-delay: calc(var(--loader-speed) * .14); }
.loader span:nth-child(4) { animation-delay: calc(var(--loader-speed) * .21); }
.loader span:nth-child(5) { animation-delay: calc(var(--loader-speed) * .28); }
.loader span:nth-child(6) { animation-delay: calc(var(--loader-speed) * .35); }
.loader::after { content: ''; position: absolute; z-index: 2; top: 0; right: 9%; width: 1.6%; height: 100%; background: color-mix(in srgb, #000 34%, var(--accent-2)); }
@keyframes tilt-slat { 0%, 12% { transform: rotateX(0deg); } 44%, 68% { transform: rotateX(74deg); } 92%, 100% { transform: rotateX(0deg); } }
